export function totalLength(rows: string[]): number {
  let sum = 0;
  for (let i = 0; i < rows.length; i++) {
    sum += rows[i].length;
  }
  return sum;
}

import { totalLength } from '../src/total.ts';
const n: number = totalLength(['ab', 'cde']);
export { n };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { totalLength } from '../src/total.ts';
test('totalLength', () => { assert.equal(totalLength(['ab', 'cde']), 5); assert.equal(totalLength([]), 0); });

